/**
 * Original Encore fan-fiction. These routes are game scenarios, not episodes,
 * recovered memories or claims about canonical events in The Amazing Digital Circus.
 */
export const STORY_NOTICE = 'Scénarios originaux pour Encore · adaptation de fan-game';
const scene = (title, opponentId, stageId, summary, a, first, b, second) => ({
  title, opponentId, stageId, summary,
  dialogue: [{ speaker: a, text: first }, { speaker: b, text: second }]
});
const route = (fighterId, title, intro, chapters, ending) => ({ fighterId, title, intro, chapters, ending });
const stories = {
  pomni: route('pomni', 'Une sortie à sa mesure',
    'Caine annonce un tournoi dont le prix serait une porte. Pomni se méfie de la promesse, mais décide de suivre le parcours pour découvrir ce que cette porte contient vraiment.', [
      scene('Le premier pas', 'ragatha', 'bigtop', 'Ragatha propose une répétition avant que le spectacle ne commence.', 'Ragatha', 'On peut commencer doucement. Tu n’as rien à prouver à toute la salle.', 'Pomni', 'Alors je vais essayer de rester ici. Juste le temps de ce premier duel.'),
      scene('La clef de Jax', 'jax', 'backstage', 'Jax prétend connaître le bon couloir et exige un duel pour montrer sa clef.', 'Jax', 'Cette clef ouvre forcément quelque chose. C’est déjà mieux qu’un panneau SORTIE.', 'Pomni', 'Garde tes énigmes. Cette fois, je choisis moi-même où je vais.'),
      scene('Le détour sucré', 'gummigoo', 'candy', 'Une simulation de Gummigoo garde le dernier passage de la course.', 'Gummigoo', 'Je connais la route jusqu’au pont. Après, il faudra décider sans carte.', 'Pomni', 'D’accord. Mais on ne laisse personne derrière pour gagner du temps.'),
      scene('La porte du prix', 'caine', 'training', 'Caine attend devant la porte promise, au centre d’une scène de calibration.', 'Caine', 'Dernier numéro ! Une victoire et cette magnifique porte est à toi !', 'Pomni', 'Avant de l’ouvrir, tu vas me dire ce que tu as mis derrière.')
    ], 'Derrière la porte se trouve une petite loge calme, créée pour la remise du prix. Pomni n’a pas quitté le cirque. Elle demande cependant à garder la clef et invite Ragatha à entrer : pour une fois, elle décide quand le rideau se ferme.'),
  jax: route('jax', 'Le gag de trop',
    'Jax remplace le programme de Caine par sa propre liste de défis. Il s’attend à regarder les autres trébucher, jusqu’à ce que le panneau affiche son nom à chaque rencontre.', [
      scene('Le masque rend les coups', 'gangle', 'spudsy', 'Gangle réclame une répétition avec des règles écrites et un public à bonne distance.', 'Jax', 'Tu as vraiment imprimé un règlement pour moi ?', 'Gangle', 'Oui. Et cette fois, tu attends la fin de ma phrase avant de rire.'),
      scene('Pièces rapportées', 'zooble', 'grounds', 'Zooble a retiré tous les accessoires piégés que Jax avait préparés.', 'Zooble', 'Tu peux utiliser tes bras, tes jambes et une idée qui ne blesse pas quelqu’un par surprise.', 'Jax', 'Ça réduit beaucoup mon répertoire.'),
      scene('La plaisanterie tombe à plat', 'ragatha', 'backstage', 'Ragatha veut savoir si Jax sait tenir une scène sans saboter son partenaire.', 'Ragatha', 'Un numéro marche mieux quand tout le monde peut encore jouer à la fin.', 'Jax', 'Très bien. Pas de trappe. Je garde le sourire, par contre.'),
      scene('Qui annonce le final ?', 'caine', 'bigtop', 'Caine transforme la dernière ligne du faux programme en duel d’improvisation.', 'Caine', 'Quelle initiative ! Tu seras donc également responsable du rangement !', 'Jax', 'Attends. Ce détail n’était pas dans ma version.')
    ], 'Jax gagne le droit de choisir le dernier gag. Il pourrait déclencher la pluie de confettis cachée au-dessus des autres, mais la retourne sur Caine. Gangle rit avant lui. Il prétend que tout était prévu et commence à ramasser les rubans.'),
  ragatha: route('ragatha', 'Le fil du spectacle',
    'Un accessoire du grand chapiteau se défait pendant les répétitions. Ragatha se porte volontaire pour remettre le numéro en place, à condition de ne pas encore devoir tout faire seule.', [
      scene('Une répétition ensemble', 'pomni', 'bigtop', 'Pomni accepte d’aider, mais hésite devant le rôle que Caine lui a donné.', 'Ragatha', 'Tu n’es pas obligée de jouer la personne qu’il a écrite sur cette fiche.', 'Pomni', 'Alors montre-moi comment on commence sans fiche.'),
      scene('L’accessoire manquant', 'bubble', 'lake', 'Bubble a transporté les pièces du décor jusqu’au lac pour les nettoyer.', 'Bubble', 'Je les ai lavées ! Certaines flottent beaucoup mieux maintenant !', 'Ragatha', 'On va déjà récupérer celles qui ont besoin de rester au sol.'),
      scene('Les petites mains', 'gloinkqueen', 'gloink', 'Les Gloinks ont emporté le dernier morceau de l’accessoire dans leur nid.', 'Ragatha', 'Tu peux garder les chutes. Il nous faut seulement cette pièce pour finir.', 'Gloink Queen', 'Le nid reconnaîtra la valeur de ton échange après ton épreuve.'),
      scene('Le droit de souffler', 'zooble', 'grounds', 'Zooble refuse de laisser Ragatha repartir directement à une nouvelle corvée.', 'Zooble', 'Ton dernier exercice : demander à quelqu’un d’autre de prendre le relais.', 'Ragatha', 'Je peux essayer. Après ce duel, tu m’aides à porter le décor ?')
    ], 'Le décor réparé tient sans que Ragatha le soutienne. Pomni noue le dernier ruban, Zooble range les outils et les autres installent les sièges. Ragatha s’assoit parmi eux avant que Caine puisse lui confier une nouvelle tâche.'),
  gangle: route('gangle', 'Derrière le masque',
    'Gangle a dessiné son propre numéro, mais la couverture de son carnet disparaît sous une pile d’affiches de Caine. Elle décide de présenter ses quatre scènes à sa manière.', [
      scene('Le cadre du dessin', 'ragatha', 'backstage', 'Ragatha découvre les esquisses et accepte de jouer la première répétition.', 'Ragatha', 'Qu’est-ce que tu veux que le public remarque en premier ?', 'Gangle', 'Le mouvement. Pas seulement si mon masque sourit.'),
      scene('Un rôle sans étiquette', 'zooble', 'training', 'Zooble teste les transitions sans imposer un rôle à Gangle.', 'Zooble', 'On peut enlever ce qui ne te ressemble pas. Même en plein milieu.', 'Gangle', 'Alors je garde les rubans. Le reste, je vais le choisir en jouant.'),
      scene('Le critique au premier rang', 'jax', 'spudsy', 'Jax s’installe devant la scène avec une liste de commentaires déjà prête.', 'Jax', 'J’ai préparé ma critique avant la première. Très efficace.', 'Gangle', 'Tu pourras la lire après. Maintenant, c’est mon tour.'),
      scene('Le carnet ouvert', 'caine', 'bigtop', 'Caine propose de remplacer le final par une avalanche d’effets.', 'Caine', 'Des explosions de couleurs ! Un feu d’artifice ! Un deuxième feu d’artifice !', 'Gangle', 'Une lumière et quelques secondes de silence. C’est tout ce qu’il me faut.')
    ], 'Le dernier ruban retombe exactement sur la ligne du dessin. Gangle laisse son carnet ouvert à côté de la scène, avec les erreurs et les corrections visibles. Les applaudissements commencent après son salut, au rythme qu’elle a choisi.'),
  zooble: route('zooble', 'À prendre ou à laisser',
    'Caine prépare une présentation intitulée « Zooble, version idéale ». Zooble accepte quatre essais pour lui montrer qu’une pièce utile n’est pas forcément la pièce qu’il préfère.', [
      scene('Essai de stabilité', 'bubble', 'lake', 'Bubble veut vérifier si la nouvelle combinaison flotte.', 'Bubble', 'Et si on ajoutait une troisième jambe ? Ou une quatrième ?', 'Zooble', 'Et si on essayait déjà avec celles que j’ai choisies ?'),
      scene('Une forme pour chaque problème', 'kinger', 'grounds', 'Kinger a construit un parcours assez étrange pour donner plusieurs solutions.', 'Kinger', 'J’ai peut-être oublié laquelle des portes était la bonne.', 'Zooble', 'Parfait. Comme ça, personne ne décidera à ma place.'),
      scene('Le costume obligatoire', 'jax', 'spudsy', 'Jax arrive avec un uniforme que Zooble n’a jamais demandé.', 'Jax', 'Ça manque de manches. Je me suis dit que tu pouvais en fournir quelques-unes.', 'Zooble', 'Tu peux garder ton uniforme. Et reculer avant la répétition.'),
      scene('Le choix reste ouvert', 'caine', 'training', 'Caine demande une configuration finale à enregistrer.', 'Caine', 'Magnifique ! Quelle version dois-je déclarer définitive ?', 'Zooble', 'Aucune. Enregistre plutôt que je peux encore changer d’avis.')
    ], 'Zooble retire la pancarte « version idéale » et la pose face contre terre. La dernière combinaison ne reste pas en place très longtemps. Le vrai prix est un petit rangement dont Zooble seul choisit le contenu.'),
  kinger: route('kinger', 'La ronde des petites lumières',
    'Des lampes de répétition clignotent dans plusieurs décors. Kinger entreprend de les vérifier avec une liste dont il oublie parfois l’ordre, mais jamais la personne qui l’accompagne.', [
      scene('Une lampe pour commencer', 'pomni', 'cellar', 'Pomni rejoint Kinger dans une salle où l’éclairage est volontairement faible.', 'Pomni', 'Tu es sûr de savoir où nous sommes ?', 'Kinger', 'Pas exactement. Mais je sais qu’on peut rester ensemble pendant qu’on cherche.'),
      scene('Le couloir qui grince', 'baronmildenhall', 'manor', 'Une simulation muette du Baron marque le passage devant les interrupteurs.', 'Narration', 'La silhouette d’archive se place sous le tableau. Aucune nouvelle parole n’est attribuée au Baron.', 'Kinger', 'Il ne répond pas. Nous pouvons quand même regarder où passent les petites lumières.'),
      scene('La boîte aux rubans', 'gangle', 'backstage', 'Gangle a fixé des repères colorés pour ne plus perdre le chemin du retour.', 'Gangle', 'Si un ruban tombe, on en pose un autre. Le parcours ne sera pas perdu.', 'Kinger', 'Excellente idée. Je vais essayer de me rappeler où j’ai posé les miens.'),
      scene('La dernière veilleuse', 'caine', 'bigtop', 'Caine veut rallumer toutes les lampes d’un seul coup.', 'Caine', 'Plus aucune ombre, plus aucun problème !', 'Kinger', 'Gardons-en une ou deux. Il y a des choses qu’on entend mieux quand tout ne brille pas.')
    ], 'Les lampes sont rallumées une à une. Kinger garde une petite veilleuse près de son fort de coussins. Quand quelqu’un hésite dans le couloir, il n’a pas besoin d’un grand discours : il déplace simplement la lumière pour lui faire une place.'),
  caine: route('caine', 'L’imprévu au programme',
    'Caine veut démontrer qu’il peut concevoir le spectacle parfait. Pour cette répétition exceptionnelle, les participants ont le droit de modifier une règle à chaque rencontre.', [
      scene('Sans accessoire supplémentaire', 'bubble', 'lake', 'Bubble réclame un numéro simple et reçoit malgré lui un nouveau formulaire.', 'Bubble', 'Ma règle : pas de formulaire !', 'Caine', 'Très bien ! Il me faut simplement le formulaire de suppression des formulaires.'),
      scene('La règle change', 'zooble', 'training', 'Zooble demande que Caine termine une répétition sans ajouter de nouvelle surprise.', 'Zooble', 'Quand une consigne marche, laisse-la tranquille pendant trente secondes.', 'Caine', 'Trente secondes entières ? Quelle proposition audacieuse !'),
      scene('Un rire sans piège', 'jax', 'grounds', 'Jax choisit un duel dont personne ne connaît la chute.', 'Jax', 'Je te laisse improviser. C’est la partie qui m’inquiète le moins.', 'Caine', 'Je suis ravi de cette confiance extrêmement ambiguë !'),
      scene('La question après le salut', 'pomni', 'bigtop', 'Pomni exige que Caine écoute sa réponse après lui avoir demandé son avis.', 'Pomni', 'Si tu demandes si on a aimé, attends vraiment la réponse.', 'Caine', 'D’accord. Je vais poser ma trompette pendant que tu parles.')
    ], 'Le compte rendu du spectacle parfait contient des phrases barrées, des silences et plusieurs « je ne sais pas ». Caine ne sait pas encore quoi en faire. Il garde pourtant la feuille, puis demande aux autres quel numéro ils voudraient répéter demain.'),
  bubble: route('bubble', 'Service impeccable',
    'Bubble reçoit une liste d’objets à nettoyer pour la prochaine représentation. Sa définition de « propre » déclenche un petit parcours de vérification à travers les décors.', [
      scene('Un lac bien rangé', 'zooble', 'lake', 'Zooble tente de récupérer ce que Bubble a fait flotter au milieu du lac.', 'Bubble', 'Plus rien ne traîne par terre !', 'Zooble', 'Parce que tout est dans l’eau. On va revoir cette méthode.'),
      scene('La bonne nappe', 'loolilalu', 'kingdom', 'La princesse demande que les décorations sucrées restent sur les tables.', 'Loolilalu', 'Ce qui brille n’est pas nécessairement une tache à enlever.', 'Bubble', 'Donc je peux laisser toutes les paillettes ? Merveilleuse nouvelle !'),
      scene('Un client très gourmand', 'fudge', 'candy', 'La simulation de Fudge inspecte un chariot que Bubble vient de vider.', 'The Fudge', 'Tu as laissé quelque chose pour moi dans ce chariot ?', 'Bubble', 'De l’espace ! Beaucoup, beaucoup d’espace !'),
      scene('Le contrôle du maître de piste', 'caine', 'bigtop', 'Caine découvre une scène nette, avec un seul détail au milieu.', 'Caine', 'Bubble, pourquoi reste-t-il cette énorme pile ?', 'Bubble', 'Tu as demandé une scène propre. Tu n’as pas parlé des coulisses !')
    ], 'Bubble obtient une nouvelle liste, plus courte : demander avant de déplacer. Il la colle fièrement sur le chariot. Le spectacle commence et, pour une fois, tous les accessoires sont encore à la place où les artistes les avaient laissés.'),
  gummigoo: route('gummigoo', 'Une route à partager',
    'Dans ce scénario de simulation, Gummigoo reçoit un convoi à guider entre quatre décors. Il veut terminer le trajet avec une équipe, plutôt qu’avec une cargaison abandonnée sur la route.', [
      scene('Le poste du palais', 'loolilalu', 'kingdom', 'Loolilalu exige un test avant de confier le chariot au convoi.', 'Loolilalu', 'La cargaison compte, mais ceux qui la transportent comptent aussi.', 'Gummigoo', 'Alors on est déjà d’accord sur la moitié du trajet.'),
      scene('La piste encombrée', 'fudge', 'candy', 'Fudge occupe le passage le plus court et propose un détour peu rassurant.', 'The Fudge', 'On peut négocier. Ça dépend de ce que tu transportes.', 'Gummigoo', 'Aujourd’hui, je protège surtout ceux qui marchent à côté du chariot.'),
      scene('Le relais', 'pomni', 'grounds', 'Pomni s’est éloignée du groupe pour vérifier la route suivante.', 'Pomni', 'Je ne voulais pas ralentir tout le monde.', 'Gummigoo', 'Tu peux nous prévenir. Un convoi, ça sert justement à ne pas rouler seul.'),
      scene('La destination choisie', 'caine', 'training', 'Caine présente une arrivée spectaculaire qui coupe la route de retour.', 'Caine', 'Une destination exclusive ! Le retour n’était pas inclus !', 'Gummigoo', 'Alors on va ajouter une ligne à ton itinéraire.')
    ], 'Le convoi revient au point de départ avec sa cargaison et tous ses compagnons. Gummigoo trace le chemin parcouru sur une carte du décor. Cette histoire reste une simulation d’Encore ; dans son dernier plan, le chariot laisse assez de place pour celui qui voudra monter.'),
  loolilalu: route('loolilalu', 'La fête des quatre passages',
    'Loolilalu prépare une réception qui doit rester accessible à tous les invités. Quatre passages du décor sont encombrés par des répétitions concurrentes ; elle part négocier chaque ouverture.', [
      scene('Le cortège', 'gummigoo', 'kingdom', 'Le convoi demande un passage assez large pour ne pas écraser les décorations.', 'Loolilalu', 'Une fête où personne ne peut entrer n’est pas une réception réussie.', 'Gummigoo', 'Laissez-nous de la place et nous livrerons tout à l’heure.'),
      scene('La grande faim', 'fudge', 'candy', 'Fudge a choisi précisément la route réservée au buffet.', 'The Fudge', 'Je reconnais une bonne invitation quand elle sent le dessert.', 'Loolilalu', 'L’invitation comprend une place à table. Pas la table entière.'),
      scene('Des décorations itinérantes', 'gloinkqueen', 'gloink', 'Le nid des Gloinks contient désormais plusieurs pièces de la réception.', 'Loolilalu', 'Je suis prête à offrir de nouveaux ornements. Les nôtres doivent revenir.', 'Gloink Queen', 'Alors montre au nid que ton offre mérite une place.'),
      scene('L’invité qui improvise', 'jax', 'bigtop', 'Jax veut transformer l’ouverture de la réception en numéro de diversion.', 'Jax', 'J’apporte une animation imprévue. C’est très recherché.', 'Loolilalu', 'Vous aurez votre tour après que tout le monde sera installé.')
    ], 'Les quatre passages restent ouverts au début de la réception. Loolilalu laisse une chaise de plus à chaque table et un espace vide au milieu de la salle. Même un invité inattendu peut désormais entrer sans interrompre toute la fête.'),
  gloinkqueen: route('gloinkqueen', 'Le trésor du nid',
    'Caine construit un parcours autour d’un trésor de spectacle. La reine veut l’emporter au nid, mais les quatre gardiens attendent autre chose qu’une collection d’objets dérobés.', [
      scene('Un objet qui bouge', 'bubble', 'gloink', 'Bubble tourne autour du trésor comme s’il s’agissait d’un accessoire à nettoyer.', 'Bubble', 'Je peux polir cette chose si personne ne l’avale pendant ce temps !', 'Gloink Queen', 'Le nid décidera de sa place après l’épreuve.'),
      scene('Le ruban de la piste', 'ragatha', 'grounds', 'Ragatha protège les éléments qui maintiennent le décor debout.', 'Ragatha', 'Tu peux collectionner les chutes. Sans ces attaches, tout va tomber.', 'Gloink Queen', 'Une structure qui tient mérite donc d’être gardée entière.'),
      scene('La pièce qui se défend', 'zooble', 'training', 'Zooble refuse fermement d’être ajouté au trésor.', 'Zooble', 'Les objets de ton décor et les gens du cirque, ce n’est pas la même chose.', 'Gloink Queen', 'Cette pièce parle beaucoup. Le nid entend son refus.'),
      scene('Un trésor à transporter', 'caine', 'bigtop', 'Caine dévoile un coffre spectaculaire, attaché à toute la scène.', 'Caine', 'Le coffre est à toi ! Les projecteurs, les gradins et moi-même ne sont pas compris !', 'Gloink Queen', 'Détache donc ton prix. Le nid n’a pas besoin de tes gradins.')
    ], 'La reine emporte le coffre préparé pour elle. Les Gloinks le garnissent des pièces abandonnées pendant les répétitions, tandis que les attaches des autres décors restent en place. Pour ce numéro, le trésor du nid est enfin quelque chose qui peut être donné.'),
  fudge: route('fudge', 'Une place au banquet',
    'Dans cette aventure de fan-game, Fudge suit l’odeur d’un banquet annoncé par Caine. Chaque arène rappelle qu’une invitation comporte quelques limites, même pour un invité de cette taille.', [
      scene('Le chariot léger', 'gummigoo', 'candy', 'Le convoi transporte les ingrédients destinés à toute la réception.', 'The Fudge', 'Un petit prélèvement ne changera pas grand-chose à votre chargement.', 'Gummigoo', 'À cette échelle, on va définir ensemble ce que veut dire petit.'),
      scene('La nappe royale', 'loolilalu', 'kingdom', 'Loolilalu montre la place réservée au grand invité.', 'Loolilalu', 'Le banquet aura une portion pour chacun.', 'The Fudge', 'La mienne demande peut-être un peu plus de place que les autres.'),
      scene('La vaisselle disparue', 'bubble', 'lake', 'Bubble et Fudge donnent des explications très différentes à une table vide.', 'Bubble', 'J’ai tout nettoyé avant le repas !', 'The Fudge', 'Alors il va falloir nous entendre sur le moment du service.'),
      scene('Le dessert du final', 'caine', 'bigtop', 'Caine présente un dessert numérique dont la taille change pendant l’annonce.', 'Caine', 'Un final garanti sans fin de faim ! Enfin, je crois que c’était la formule.', 'The Fudge', 'Commençons par une portion qui reste en place.')
    ], 'Fudge reçoit une table adaptée et un dessert qui ne cherche pas à s’enfuir. Il laisse le chariot repartir avant de commencer. Le rideau tombe sur un banquet un peu encombré, mais où les autres invités ont encore quelque chose dans leur assiette.'),
  abstractedkaufmo: route('abstractedkaufmo', 'L’écho sous le rideau',
    'Cette route met en scène une construction d’archive d’Encore. Elle ne raconte ni un retour ni une guérison de Kaufmo : les autres artistes traversent quatre tableaux pour contenir un écho de spectacle.', [
      scene('La répétition interrompue', 'ragatha', 'backstage', 'Des silhouettes de décor se replient devant les formes instables de l’écho.', 'Ragatha', 'On garde de la distance. Personne ne joue cette scène seul.', 'Narration', 'La construction abstraite répond par une vibration de lumière, sans parole humaine.'),
      scene('Des repères dans le noir', 'kinger', 'cellar', 'Kinger suit les signes lumineux jusqu’au dispositif de confinement.', 'Kinger', 'Je vois les repères. Il suffit d’en garder un en vue à la fois.', 'Narration', 'Les yeux de la silhouette s’orientent vers la lampe. Le passage derrière elle reste ouvert.'),
      scene('Un ruban pour la sortie', 'pomni', 'void', 'Pomni fixe un lien au décor pour retrouver le chemin sans s’approcher davantage.', 'Pomni', 'Ce n’est pas une porte. C’est juste un repère pour revenir.', 'Narration', 'L’écho traverse les marques au sol et les reforme à chaque mouvement.'),
      scene('La fermeture du tableau', 'caine', 'training', 'Caine ramène la construction dans l’espace prévu pour la simulation.', 'Caine', 'Fin de ce numéro. Je ferme le tableau et je rends la scène aux artistes.', 'Narration', 'Les contours se resserrent autour de la construction, puis la lumière de l’arène baisse.')
    ], 'La scène d’archive s’éteint sans révélation sur Kaufmo. Le carnet d’Encore conserve seulement les gestes des artistes qui sont restés ensemble et ont maintenu une issue libre. Le siège marqué de son nom demeure hors de la représentation.'),
  baronmildenhall: route('baronmildenhall', 'Le dernier invité du manoir',
    'Encore monte une visite du manoir autour d’une silhouette d’archive du Baron Mildenhall. Cette simulation muette sert de repère à quatre épreuves : elle n’est ni un retour du personnage, ni un nouvel enregistrement de sa voix.', [
      scene('Une lumière de travers', 'kinger', 'manor', 'Kinger observe les recoins au lieu du tableau accroché dans l’entrée.', 'Narration', 'La silhouette reste dans le cadre pendant que la lumière révèle les angles du couloir.', 'Kinger', 'C’est justement ce que je regardais. Il y a peut-être quelque chose de petit par ici.'),
      scene('Le pas hésitant', 'pomni', 'cellar', 'Pomni avance en comptant les marches qui séparent la salle de l’escalier.', 'Pomni', 'Je préfère savoir comment ressortir avant de regarder la décoration.', 'Narration', 'La visite laisse les marches éclairées. Le tableau ne répond pas à Pomni.'),
      scene('Le visiteur bruyant', 'jax', 'backstage', 'Jax manipule les accessoires de la visite comme s’ils lui appartenaient.', 'Jax', 'Vous avez une collection impressionnante de choses qui grincent.', 'Narration', 'Un volet du décor se rabat devant l’accessoire. C’est un mécanisme de la répétition, pas une réaction prêtée au Baron.'),
      scene('Le propriétaire du décor', 'caine', 'bigtop', 'Caine veut accélérer la visite en supprimant la moitié des couloirs.', 'Caine', 'Une visite express ! Personne ne pourra se perdre !', 'Narration', 'Le parcours conserve ses quatre repères. Le dernier duel décide où poser le panneau de sortie.')
    ], 'La projection d’Encore s’arrête ; le Baron ne reçoit ni voix nouvelle ni conclusion inventée à son histoire. Kinger et Pomni replacent les repères de la visite. Les couloirs gardent leurs détours, mais la sortie reste visible depuis la dernière scène.')
};

